import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Container, Form, FormGroup, Button } from 'reactstrap';
import { BASE_URL } from '../../utils/config';

const CreateTour = () => {
   const { id } = useParams(); // Lấy id từ URL nếu là trang Update
   const isUpdateMode = !!id; // Nếu có id thì là TRUE (chế độ cập nhật)
   const navigate = useNavigate();

   const [formData, setFormData] = useState({
      title: '', city: '', address: '', distance: 0,
      price: 0, maxGroupSize: 0, desc: '', featured: false
   });
   const [mainPhoto, setMainPhoto] = useState(null);
   const [galleryPhotos, setGalleryPhotos] = useState([]);

   // NẾU LÀ UPDATE: Phải lấy dữ liệu cũ về để đổ vào Form
   useEffect(() => {
      if (isUpdateMode) {
         const fetchTourData = async () => {
            const res = await fetch(`${BASE_URL}/tours/${id}`);
            const result = await res.json();
            if (res.ok) {
               setFormData(result.data); // Đổ dữ liệu cũ vào form
            }
         };
         fetchTourData();
      }
   }, [id, isUpdateMode]);

   const handleChange = e => {
      setFormData(prev => ({ ...prev, [e.target.id]: e.target.value }));
   };

   const handleSubmit = async (e) => {
      e.preventDefault();
      const token = localStorage.getItem('token');
      const data = new FormData();
      
      Object.keys(formData).forEach(key => {
         // Nếu là update, bỏ qua trường reviews để tránh lỗi logic
         if(key !== 'reviews') data.append(key, formData[key]);
      });

      if (mainPhoto) data.append('photo', mainPhoto);
      galleryPhotos.forEach(file => data.append('images', file));

      try {
         // CHỌN URL VÀ METHOD TÙY THEO CHẾ ĐỘ
         const url = isUpdateMode ? `${BASE_URL}/tours/${id}` : `${BASE_URL}/tours`;
         const method = isUpdateMode ? 'PUT' : 'POST';

         const res = await fetch(url, {
            method: method,
            headers: { 'Authorization': `Bearer ${token}` },
            body: data
         });

         if (res.ok) {
            alert(isUpdateMode ? "Cập nhật thành công!" : "Tạo mới thành công!");
            navigate('/admin/dashboard'); // Xong thì về trang quản lý
         }
      } catch (err) {
         alert("Có lỗi xảy ra!");
      }
   };

   return (
      <Container className="mt-5 pt-5">
         <h3 className="mb-4">{isUpdateMode ? "Chỉnh sửa Tour" : "Thêm Tour Mới"}</h3>
         <Form onSubmit={handleSubmit}>
            <FormGroup>
               <label>Tên Tour</label>
               <input 
                  type="text" 
                  id="title" 
                  value={formData.title} // Để value để hiện dữ liệu cũ khi update
                  onChange={handleChange} 
                  className="form-control" 
                  required 
               />
            </FormGroup>
            
            {/* Các input khác làm tương tự (nhớ thêm value={formData...}) */}

            <FormGroup>
               <label>Ảnh hiện tại:</label>
               {isUpdateMode && formData.photo && (
                  <div className="mb-2">
                     <img src={`http://localhost:4000/static-number-one/${formData.photo}`} width="100" />
                  </div>
               )}
               <input type="file" onChange={e => setMainPhoto(e.target.files[0])} className="form-control" />
            </FormGroup>

            <Button type="submit" color={isUpdateMode ? "success" : "primary"}>
               {isUpdateMode ? "Lưu thay đổi" : "Tạo Tour"}
            </Button>
         </Form>
      </Container>
   );
};

export default CreateTour;
